public class SecondLargestFinder {

    /**
     * Finds the second largest distinct element in an integer array.
     * @param arr The input array of integers
     * @return The second largest distinct element, or Integer.MIN_VALUE if not found
     */
    public static int findSecondLargest(int[] arr) {
        // Handle edge cases: null or empty array, or less than 2 elements
        if (arr == null || arr.length < 2) {
            return Integer.MIN_VALUE;
        }

        // Initialize first and second largest with minimum values
        int firstLargest = Integer.MIN_VALUE;
