        for (int num : arr) {
            // If current number is greater than the first largest
            if (num > firstLargest) {
                secondLargest = firstLargest;  // First becomes second
                firstLargest = num;             // Update first largest
            }
            // If current number is between first and second largest (and not equal to first)
            else if (num < firstLargest && num > secondLargest) {
                secondLargest = num;
            }
        }

        return secondLargest;
    }

    // Example usage
    public static void main(String[] args) {
        int[] arr1 = {5, 2, 9, 1, 7, 9};
        int result1 = findSecondLargest(arr1);
        System.out.println("Array: " + java.util.Arrays.toString(arr1));
        System.out.println("Second largest distinct element: " + result1); // Output: 7

        int[] arr2 = {10, 10};
